def slugify(s):
    s = s.lower()
    # Decompose and drop combining marks so diacritics (e.g. õ -> o) resolve.
    s = unicodedata.normalize('NFD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))

    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')

    return '-'.join(part for part in ''.join(out).split('-') if part)

